1	//! Removes ranked blocks that mostly repeat a better-ranked block in the same file.
2	
3	use crate::types::{CodeBlock, RankedBlock};
4	
5	/// Drops each block that overlaps an earlier kept block in the same file by more than half of the smaller block's
6	/// lines, then reassigns 1-based ranks.
7	///
8	/// The input is expected best first, as [`rank_blocks`](crate::rank::rank_blocks) returns it, so the better block of
9	/// an overlapping pair survives. Blocks in different files never dedupe. A block whose `line_end` is before its
10	/// `line_start` overlaps nothing and is always kept.
11	///
12	/// A member (a block with a `parent`) never duplicates the top-level block that strictly encloses it, in either rank
13	/// order: the enclosing block holds the member by design. Two members, or two blocks without a parent, dedupe by
14	/// overlap as above even when one lies inside the other.
15	///
16	/// # Examples
17	///
18	/// ```
19	/// use camino::Utf8PathBuf;
20	/// use monokl::dedup::dedup_blocks;
21	/// use monokl::types::{CodeBlock, RankedBlock, SymbolKind};
22	///
23	/// let ranked = |line_start, line_end, rank| RankedBlock {
24	///     block: CodeBlock {
25	///         file: Utf8PathBuf::from("src/a.ts"),
26	///         line_start,
27	///         line_end,
28	///         node_kind: SymbolKind::Function,
29	///         code: String::new(),
30	///         symbol_signature: None,
31	///         matched_lines: Vec::new(),
32	///         matched_keywords: Vec::new(),
33	///         parent: None,
34	///     },
35	///     bm25_score: 0.0,
36	///     coverage_boost: 0.0,
37	///     node_type_boost: 1.5,
38	///     final_score: 0.0,
39	///     rank,
40	///     parent_context: None,
41	/// };
42	/// let kept = dedup_blocks(vec![ranked(1, 10, 1), ranked(5, 10, 2), ranked(20, 30, 3)]);
43	/// let kept: Vec<_> = kept.iter().map(|r| (r.block.line_start, r.rank)).collect();
44	/// assert_eq!(kept, [(1, 1), (20, 2)]);
45	/// ```
46	pub fn dedup_blocks(blocks: Vec<RankedBlock>) -> Vec<RankedBlock> {
47	    let mut kept: Vec<RankedBlock> = Vec::with_capacity(blocks.len());
48	    for block in blocks {
49	        let is_duplicate = kept.iter().any(|earlier| {
50	            earlier.block.file == block.block.file
51	                && !encloses_member(&earlier.block, &block.block)
52	                && !encloses_member(&block.block, &earlier.block)
53	                && overlaps_significantly(&earlier.block, &block.block)
54	        });
55	        if !is_duplicate {
56	            kept.push(block);
57	        }
58	    }
59	    for (rank, block) in (1..).zip(&mut kept) {
60	        block.rank = rank;
61	    }
62	    kept
63	}
64	
65	/// Returns whether `member` has a parent and lies strictly inside `outer`, a block that has none.
66	fn encloses_member(outer: &CodeBlock, member: &CodeBlock) -> bool {
67	    member.parent.is_some()
68	        && outer.parent.is_none()
69	        && outer.line_start <= member.line_start
70	        && member.line_end <= outer.line_end
71	        && (outer.line_start, outer.line_end) != (member.line_start, member.line_end)
72	}
73	
74	/// Returns whether the two line ranges share more than half of the smaller range's lines.
75	fn overlaps_significantly(a: &CodeBlock, b: &CodeBlock) -> bool {
76	    let overlap_start = a.line_start.max(b.line_start);
77	    let overlap_end = a.line_end.min(b.line_end);
78	    if overlap_start > overlap_end {
79	        return false;
80	    }
81	    let overlap_lines = overlap_end - overlap_start + 1;
82	    // Nothing guarantees `line_start <= line_end`, so the lengths saturate rather than risk an underflow panic.
83	    let smaller_len = (a.line_end.saturating_sub(a.line_start) + 1).min(b.line_end.saturating_sub(b.line_start) + 1);
84	    overlap_lines * 2 > smaller_len
85	}
86	
