        let expected = quadratic_reference(&blocks);
        let actual: Vec<_> = dedup_blocks(blocks)
            .iter()
            .map(|r| (r.block.file.clone(), r.block.line_start, r.block.line_end, r.rank))
            .collect();
        prop_assert_eq!(actual, expected);
    }
}
