    /// Returns whether `is_duplicate` holds for any kept block whose lines intersect `line_start..=line_end`, trying
    /// them in slot order and stopping at the first that holds.
    fn any_kept_overlap(
        &self,
        line_start: usize,
        line_end: usize,
        mut is_duplicate: impl FnMut(usize) -> bool,
    ) -> bool {
        let starting_by_end = self.starts.partition_point(|&start| start <= line_end);
        self.visit(1, 0, self.leaf_count, starting_by_end, line_start, &mut is_duplicate)
    }

    /// Searches the slots of `lo..hi` below `node` that precede `limit` and end at or after `min_end`.
    fn visit(
        &self,
        node: usize,
        lo: usize,
        hi: usize,
        limit: usize,
        min_end: usize,
        is_duplicate: &mut impl FnMut(usize) -> bool,
    ) -> bool {
        if lo >= limit || self.max_end[node].is_none_or(|end| end < min_end) {
            return false;
        }
        if hi - lo == 1 {
            return is_duplicate(self.blocks[lo]);
        }
        let mid = lo + (hi - lo) / 2;
        self.visit(2 * node, lo, mid, limit, min_end, is_duplicate)
            || self.visit(2 * node + 1, mid, hi, limit, min_end, is_duplicate)
    }
}

/// Returns whether `member` has a parent and lies strictly inside `outer`, a block that has none.
fn encloses_member(outer: &CodeBlock, member: &CodeBlock) -> bool {
    member.parent.is_some()
        && outer.parent.is_none()
        && outer.line_start <= member.line_start
        && member.line_end <= outer.line_end
        && (outer.line_start, outer.line_end) != (member.line_start, member.line_end)
}

